    if number < 0:
        raise ValueError("Cannot compute the square root of a negative number.")
    if number == 0:
        return 0.0

    guess = number / 2.0
    if guess == 0:
        guess = 1.0

    while True:
        next_guess = (guess + number / guess) / 2.0
        if abs(guess - next_guess) < 1e-12:
            return next_guess
        guess = next_guess

