def parse_record(line):
    """Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal, \\" is an escaped
      quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.

    parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    """
    fields = []
    current = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        c = line[i]
        if c == '\\' and in_quotes and i + 1 < n and line[i + 1] == '"':
            current.append('\\"')
            i += 2
            continue
        elif c == '"':
            in_quotes = not in_quotes
            current.append(c)
        elif c == ';' and not in_quotes:
            fields.append("".join(current))
            current = []
        else:
            current.append(c)
        i += 1
    fields.append("".join(current))

    result = {}
    for field in fields:
        field_str = field.strip()
        if not field_str:
            continue

        eq_idx = -1
        in_q = False
        j = 0
        while j < len(field_str):
            c = field_str[j]
            if c == '\\' and in_q and j + 1 < len(field_str) and field_str[j + 1] == '"':
                j += 2
                continue
            elif c == '"':
                in_q = not in_q
            elif c == '=' and not in_q:
                eq_idx = j
                break
            j += 1

        if eq_idx == -1:
            result[field_str] = True
        else:
            key = field_str[:eq_idx].strip()
            val = field_str[eq_idx + 1:].strip()
            if len(val) >= 2 and val.startswith('"') and val.endswith('"'):
                val = val[1:-1].replace('\\"', '"')
            result[key] = val

    return result

