def babylonian_squareroot(number):
    if number < 0:
        raise ValueError("Cannot compute square root of a negative number.")
    if number == 0:
        return 0.0

    x = float(number)
    y = 1.0
    e = 0.00000000001

    while (x - y) > e:
        x = (x + y) / 2.0
        y = number / x

    return x

