    """
    fields = []
    current = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        c = line[i]
        if in_quotes:
            if c == '\\' and i + 1 < n and line[i + 1] == '"':
                current.append('\\"')
                i += 2
                continue
            elif c == '"':
                in_quotes = False
                current.append(c)
            else:
                current.append(c)
        else:
            if c == '"':
                in_quotes = True
                current.append(c)
            elif c == ';':
                fields.append("".join(current))
                current = []
            else:
                current.append(c)
        i += 1

    if current:
        fields.append("".join(current))

    result = {}
    for field in fields:
        if not field.strip():
            continue
        if '=' in field:
            key, val = field.split('=', 1)
            key = key.strip()
            val = val.strip()
            if len(val) >= 2 and val.startswith('"') and val.endswith('"'):
                val = val[1:-1].replace('\\"', '"')
            result[key] = val
        else:
            key = field.strip()
            result[key] = True

    return result

